import { fileURLToPath } from "node:url";

import { tinker } from "@tinker/start/vite";
import { defineConfig } from "vite-plus";

export default defineConfig({
  fmt: {
    sortImports: {
      customGroups: [{ groupName: "base", elementNamePattern: ["~/**"] }],
      groups: ["builtin", "external", "base", "internal", ["parent", "sibling", "index"]],
    },
  },
  resolve: {
    alias: {
      "@": fileURLToPath(new URL("./src", import.meta.url)),
      "~": fileURLToPath(new URL("./tinker", import.meta.url)),
    },
  },
  plugins: [tinker({ serverEntry: "cmds/server.ts" })],
});

import { createScope } from "@tinker/core";
import * as start from "@tinker/start/server";

import { backendStop, createScopeClose, createServerEntry } from "~/base/server";

const values = { ...process.env };
const appTags = [start.auth.settings(values)];
const stop = { tools: new AbortController(), app: new AbortController() };

const tools = createScope({
  signal: stop.tools.signal,
  extensions: start.telemetry.extensions,
  tags: [start.telemetry.settings(values), start.telemetry.tags],
});

await tools.ready;

const app = createScope({
  signal: stop.app.signal,
  observe: tools.resolve(start.telemetry.observe),
  extensions: [start.startRequests, start.auth.extensions],
  tags: [backendStop(stop.app.signal), appTags, tools.resolve(start.telemetry.appTags)],
});

const close = createScopeClose({ tools, app }, stop);

await app.ready.catch(close);

const server = createServerEntry({
  requestContext: app.resolve(start.startRequests),
  renderObserve: tools.resolve(start.telemetry.renderObserve, { ns: start.telemetry.renderNs }),
  close,
});

if (import.meta.hot) import.meta.hot.dispose(close);
export default server;

import type { RouterOptions } from "@tinker/start";

export const extensions = [];
export const router: RouterOptions = () => ({});

import { operation } from "@tinker/core";
import { z } from "zod";

export const greet = operation({
  label: "greet",
  input: z.object({ name: z.string().min(1) }),
  run: (_deps, { input }) => ({ text: `Hello, ${input.name}.` }),
});

import { createServerFn } from "@tanstack/react-start";
import { startRequests } from "@tinker/start";
import { readResult } from "@tinker/start/server";

import { greet } from "@/backend/greet";

export const runGreet = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) =>
    readResult(
      await context.session.settle(greet, {
        input: { name: "world" },
        signal: context.signal,
      }),
    ),
  );

import { createFileRoute } from "@tanstack/react-router";

import { runGreet } from "@/transport/greet.functions";

export const Route = createFileRoute("/")({
  loader: () => runGreet(),
  component: () => <p>{Route.useLoaderData().text}</p>,
});

import { tag } from "@tinker/core";
import type { Scope } from "@tinker/core";
import type { ServerEntry } from "@tinker/start/server";

/** The main supplies its original host signal, before graceful drain joins held requests. */
export const backendStop = tag<AbortSignal>({ label: "lifetime.backendStop" });
const closedReason = { kind: "server.closed" };

/** Unhandled process work is reported and closes the main before exit; no scope starts here. */
export function createServerEntry(entry: ServerEntry.Handle): ServerEntry.Handle {
  const fail = async (error: unknown) => {
    process.stderr.write(`server: unhandled rejection ${String(error)}\n`);
    try {
      await entry.close();
    } finally {
      process.exit(1);
    }
  };

  process.on("unhandledRejection", fail);
  entry.requestContext.scope.onClose(() => {
    process.off("unhandledRejection", fail);
  });
  return entry;
}

/** The main retains named roots in start order and stop controllers with the same names; repeated close calls share one promise. */
export function createScopeClose<T extends Record<string, Scope.RootHandle>>(
  roots: T,
  stop: Record<keyof T, AbortController>,
): () => Promise<void> {
  let closed: Promise<void> | undefined;
  return () => (closed ??= closeRoots(roots, stop));
}

async function closeRoots(
  roots: Record<string, Scope.RootHandle>,
  stop: Record<string, AbortController>,
): Promise<void> {
  const results: Scope.Result[] = [];
  for (const [name, scope] of Object.entries(roots).toReversed()) {
    stop[name].abort(closedReason);
    results.push(await scope.closed);
  }

  for (const result of results) {
    if (result.status === "failed") throw result.error;
    if (result.teardownErrors?.length) throw result.teardownErrors.at(0);
  }
}
